//! Byte-exact oracle test of [`taky_xml::serialize`] against `lxml.etree.tostring`
//! (`fixtures/lxml_serialize.json`, generated by `fixtures/gen_lxml_serialize.py`).
//!
//! Item kinds: `stream` (events emitted by the TreeBuilder for every CoT vector connection and
//! hand-written cases), `doc` (`parse_element` roots), `moved` (`detail` re-parented under a new
//! `<event>` after [`Element::reconcile_moved_ns`], as `Event.as_element` does) and `tree`
//! (elements built in code from a JSON spec). Every output must match byte-for-byte.
#![allow(clippy::unwrap_used)] // test helpers outside #[test] fns

mod common;

use common::b64;
use serde_json::Value;
use taky_xml::{Element, Limits, Node, SerOpts, TreeBuilder, parse_element, serialize};

/// Items skipped because the *parser* diverges from lxml there (accepted in S-303, see
/// `tests/lxml_oracle.rs` DIVERGENCES): id prefix → reason.
const PARSER_DIVERGENCES: &[(&str, &str)] = &[(
    "V054/",
    "unknown entity: libxml2 restarts as a bare document (S-303 quirk_unknown_entity_restart)",
)];

/// `TAKY_XML_SER_ORACLE=<file.json>` runs the oracle test on another file of the same format
/// (e.g. a large random differential set generated outside the repo).
fn fixture() -> Value {
    let p = std::env::var("TAKY_XML_SER_ORACLE").unwrap_or_else(|_| {
        concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/tests/fixtures/lxml_serialize.json"
        )
        .to_owned()
    });
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

fn opts(v: &Value) -> SerOpts {
    let flag = |k: &str| v.get(k).and_then(Value::as_bool);
    SerOpts {
        pretty_print: flag("pretty_print").unwrap_or(false),
        xml_declaration: flag("xml_declaration").unwrap_or(false),
        standalone: flag("standalone"),
        with_tail: flag("with_tail").unwrap_or(true),
    }
}

fn opt_str(v: &Value) -> Option<String> {
    v.as_str().map(str::to_owned)
}

/// Same builder as `build()` in the generator.
fn build(spec: &Value) -> Element {
    let mut e = Element::new(spec["tag"].as_str().unwrap());
    if let Some(ns) = spec.get("nsmap").and_then(Value::as_array) {
        for d in ns {
            e.nsmap
                .push((opt_str(&d[0]), d[1].as_str().unwrap().to_owned()));
        }
    }
    for a in spec["attrs"].as_array().unwrap() {
        e.set(a[0].as_str().unwrap(), a[1].as_str().unwrap());
    }
    e.text = opt_str(&spec["text"]);
    e.tail = opt_str(&spec["tail"]);
    for c in spec["children"].as_array().unwrap() {
        if c.get("comment").is_some() {
            e.children.push(Node::Comment {
                text: c["comment"].as_str().unwrap_or("").to_owned(),
                tail: opt_str(&c["tail"]),
            });
        } else {
            e.append(build(c));
        }
    }
    e
}

fn stream_events(item: &Value) -> Vec<Element> {
    let mut tb = TreeBuilder::new(Limits::DEFAULT);
    let mut out = Vec::new();
    for c in item["chunks_b64"].as_array().unwrap() {
        if tb.feed(&b64(c.as_str().unwrap())).is_err() {
            break;
        }
        while let Some(e) = tb.next_element().unwrap() {
            out.push(e);
        }
    }
    out
}

fn moved(input: &str) -> Element {
    let root = parse_element(input.as_bytes(), &Limits::DEFAULT).unwrap();
    let mut detail = root.find("detail").unwrap().clone();
    detail.reconcile_moved_ns();
    let mut n = Element::new("event");
    n.append(detail);
    n
}

fn text(b: &[u8]) -> String {
    String::from_utf8_lossy(b).into_owned()
}

#[test]
fn matches_lxml_tostring() {
    let fx = fixture();
    let (mut total, mut failed) = (0usize, Vec::new());
    for item in fx["items"].as_array().unwrap() {
        let id = item["id"].as_str().unwrap();
        let kind = item["kind"].as_str().unwrap();
        if PARSER_DIVERGENCES.iter().any(|(p, _)| id.starts_with(p)) {
            continue;
        }
        let elements: Vec<Element> = match kind {
            "stream" => stream_events(item),
            "doc" => vec![
                parse_element(item["input"].as_str().unwrap().as_bytes(), &Limits::DEFAULT)
                    .unwrap(),
            ],
            "moved" => vec![moved(item["input"].as_str().unwrap())],
            "tree" => vec![build(&item["tree"])],
            k => panic!("unknown kind {k}"),
        };
        for out in item["outputs"].as_array().unwrap() {
            let o = opts(&out["opts"]);
            let expect: Vec<&str> = match &out["expect"] {
                Value::Array(a) => a.iter().map(|x| x.as_str().unwrap()).collect(),
                x => vec![x.as_str().unwrap()],
            };
            total += expect.len();
            if elements.len() != expect.len() {
                failed.push(format!(
                    "{id} {o:?}: {} events, lxml {}",
                    elements.len(),
                    expect.len()
                ));
                continue;
            }
            for (e, x) in elements.iter().zip(&expect) {
                let got = serialize(e, &o);
                if got != x.as_bytes() {
                    failed.push(format!(
                        "{id} ({kind}) {o:?}\n  rust: {:?}\n  lxml: {x:?}",
                        text(&got)
                    ));
                }
            }
        }
    }
    assert!(
        total > 600 || std::env::var_os("TAKY_XML_SER_ORACLE").is_some(),
        "fixture too small: {total}"
    );
    assert!(
        failed.is_empty(),
        "{} of {total} serializations differ from lxml:\n{}",
        failed.len(),
        failed.join("\n")
    );
    eprintln!("lxml_serialize: {total}/{total} byte-exact");
}

#[test]
fn reconcile_is_idempotent() {
    let input = "<event xmlns:x='u' xmlns:y='v'><detail y:k='2'><x:foo x:k='1'/><a xmlns:z='u'><z:b/></a></detail></event>";
    let once = moved(input);
    let mut twice = once.clone();
    if let Some(Node::Element(d)) = twice.children.first_mut() {
        d.reconcile_moved_ns();
    }
    assert_eq!(once, twice);
}

#[test]
fn missing_attributes_are_omitted() {
    // arch01 (S-204): an absent `version`/`how` is not written, never as an empty value.
    let mut e = Element::new("event");
    e.set("uid", "U");
    e.set("type", "");
    assert_eq!(
        serialize(&e, &SerOpts::default()),
        b"<event uid=\"U\" type=\"\"/>"
    );
}
